import { createHash } from "node:crypto"

import type { Model } from "~/services/copilot/get-models"

import packageJson from "../../package.json"

/**
 * Identifies proxy-owned translation semantics only. Bump this token when
 * externally observable request or response translation changes. It is
 * deliberately not derived from the package version, and it makes no claim
 * about upstream Copilot behavior.
 */
export const TRANSLATION_CONTRACT = "copilot-api.translation/1"

export const UNKNOWN_MARKER = "unknown"

const REVISION_PATTERN = /^[\w.-]{1,64}$/

/**
 * Build revisions are operator-supplied, so anything that could smuggle header
 * separators, paths or identity is rejected in favour of an explicit unknown.
 */
export function sanitizeRevision(raw: string | undefined): string {
  const trimmed = raw?.trim() ?? ""
  return REVISION_PATTERN.test(trimmed) ? trimmed : UNKNOWN_MARKER
}

export const BUILD_REVISION = sanitizeRevision(
  process.env.COPILOT_API_BUILD_REVISION,
)

export const BUILD_IDENTITY = `${packageJson.version}+${BUILD_REVISION}`

function compareStrings(a: string, b: string): number {
  if (a === b) return 0
  return a < b ? -1 : 1
}

function stableStringify(value: unknown): string {
  if (value === undefined) return "null"
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value)
  }
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableStringify(item)).join(",")}]`
  }
  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([, item]) => item !== undefined)
    .sort(([a], [b]) => compareStrings(a, b))
  return `{${entries
    .map(([key, item]) => `${JSON.stringify(key)}:${stableStringify(item)}`)
    .join(",")}}`
}

/**
 * Fingerprints only the catalog fields that influence routing, normalized so
 * that upstream response ordering and key ordering cannot change the result.
 * Upstream publishes no catalog version, generation or ETag, so this proxy is
 * the only component able to identify the catalog it actually routed on.
 */
export function catalogFingerprint(models: Array<Model> | undefined): string {
  if (!models || models.length === 0) return UNKNOWN_MARKER

  const normalized = models
    .map((model) => ({
      capabilities: model.capabilities,
      id: model.id,
      supported_endpoints: [...(model.supported_endpoints ?? [])].sort(
        compareStrings,
      ),
    }))
    .sort((a, b) => compareStrings(a.id, b.id))

  return createHash("sha256")
    .update(stableStringify(normalized))
    .digest("hex")
    .slice(0, 16)
}

import { describe, expect, it } from "bun:test"

import type { Model } from "~/services/copilot/get-models"

import packageJson from "../../package.json"
import {
  BUILD_IDENTITY,
  catalogFingerprint,
  sanitizeRevision,
  TRANSLATION_CONTRACT,
  UNKNOWN_MARKER,
} from "./build-info"

function model(overrides: Partial<Model> = {}): Model {
  return {
    id: "gpt-test",
    name: "GPT Test",
    object: "model",
    vendor: "openai",
    version: "1",
    preview: false,
    model_picker_enabled: true,
    supported_endpoints: ["/responses"],
    capabilities: {
      family: "gpt",
      limits: { max_output_tokens: 128 },
      object: "model_capabilities",
      supports: { tool_calls: true },
      tokenizer: "test",
      type: "chat",
    },
    ...overrides,
  }
}

describe("build revision sanitization", () => {
  it.each([undefined, "", "   "])("falls back to unknown for %p", (raw) => {
    expect(sanitizeRevision(raw)).toBe(UNKNOWN_MARKER)
  })

  it.each(["abc1234", "1.2.3", "v0.7.0-rc.1", "a".repeat(64)])(
    "accepts the safe revision %p",
    (raw) => {
      expect(sanitizeRevision(raw)).toBe(raw)
    },
  )

  it("trims surrounding whitespace", () => {
    expect(sanitizeRevision("  abc1234  ")).toBe("abc1234")
  })

  it.each([
    "a".repeat(65),
    "has space",
    "semi;colon",
    "new\nline",
    "/etc/passwd",
    "user@example.com",
    "ghp_secrettokenvalue!",
  ])("rejects the unsafe revision %p", (raw) => {
    expect(sanitizeRevision(raw)).toBe(UNKNOWN_MARKER)
  })

  it("reports the package version alongside the revision", () => {
    expect(BUILD_IDENTITY.startsWith(`${packageJson.version}+`)).toBe(true)
  })
})

describe("translation contract token", () => {
  it("is a stable constant that is not the package version", () => {
    expect(TRANSLATION_CONTRACT).toBe("copilot-api.translation/1")
    expect(TRANSLATION_CONTRACT).not.toContain(packageJson.version)
  })
})

describe("catalog fingerprint", () => {
  it("returns unknown when no catalog is loaded", () => {
    expect(catalogFingerprint(undefined)).toBe(UNKNOWN_MARKER)
    expect(catalogFingerprint([])).toBe(UNKNOWN_MARKER)
  })

  it("is stable for the same catalog content", () => {
    const first = catalogFingerprint([model({ id: "a" }), model({ id: "b" })])
    const second = catalogFingerprint([model({ id: "a" }), model({ id: "b" })])
    expect(first).toBe(second)
  })

  it("ignores upstream response ordering", () => {
    const ordered = catalogFingerprint([model({ id: "a" }), model({ id: "b" })])
    const reversed = catalogFingerprint([
      model({ id: "b" }),
      model({ id: "a" }),
    ])
    expect(reversed).toBe(ordered)
  })

  it("ignores endpoint ordering within a model", () => {
    const ordered = catalogFingerprint([
      model({ supported_endpoints: ["/chat/completions", "/responses"] }),
    ])
    const reversed = catalogFingerprint([
      model({ supported_endpoints: ["/responses", "/chat/completions"] }),
    ])
    expect(reversed).toBe(ordered)
  })

  it("ignores fields that do not affect routing", () => {
    const base = catalogFingerprint([model()])
    const noisy = catalogFingerprint([
      model({
        name: "Renamed",
        preview: true,
        model_picker_enabled: false,
        model_picker_category: "powerful",
        version: "2",
      }),
    ])
    expect(noisy).toBe(base)
  })

  it("changes when a model is added", () => {
    const before = catalogFingerprint([model({ id: "a" })])
    const after = catalogFingerprint([model({ id: "a" }), model({ id: "b" })])
    expect(after).not.toBe(before)
  })

  it("changes when supported endpoints change", () => {
    const before = catalogFingerprint([
      model({ supported_endpoints: ["/responses"] }),
    ])
    const after = catalogFingerprint([
      model({ supported_endpoints: ["/chat/completions"] }),
    ])
    expect(after).not.toBe(before)
  })

  it("changes when capabilities change", () => {
    const before = catalogFingerprint([model()])
    const after = catalogFingerprint([
      model({
        capabilities: {
          family: "gpt",
          limits: { max_output_tokens: 256 },
          object: "model_capabilities",
          supports: { tool_calls: true },
          tokenizer: "test",
          type: "chat",
        },
      }),
    ])
    expect(after).not.toBe(before)
  })

  it("is a one-way digest that leaks no catalog content", () => {
    const fingerprint = catalogFingerprint([model({ id: "secret-model" })])
    expect(fingerprint).toMatch(/^[0-9a-f]{16}$/)
    expect(fingerprint).not.toContain("secret-model")
  })
})

import consola from "consola"

import { getModels } from "~/services/copilot/get-models"
import { getVSCodeVersion } from "~/services/get-vscode-version"

import { catalogFingerprint } from "./build-info"
import { state } from "./state"

export const sleep = (ms: number) =>
  new Promise((resolve) => {
    setTimeout(resolve, ms)
  })

export const isNullish = (value: unknown): value is null | undefined =>
  value === null || value === undefined

export async function cacheModels(): Promise<void> {
  const models = await getModels()
  state.models = models
  state.modelsObservedAt = new Date().toISOString()
  state.modelsFingerprint = catalogFingerprint(models.data)
}

export const cacheVSCodeVersion = async () => {
  const response = await getVSCodeVersion()
  state.vsCodeVersion = response

  consola.info(`Using VSCode version: ${response}`)
}

import { Hono } from "hono"

import {
  BUILD_IDENTITY,
  TRANSLATION_CONTRACT,
  UNKNOWN_MARKER,
} from "~/lib/build-info"
import { pricingForModel, readCopilotPricing } from "~/lib/copilot-pricing"
import { forwardError } from "~/lib/error"
import { filterModels } from "~/lib/filter-models"
import { state } from "~/lib/state"
import { cacheModels } from "~/lib/utils"

export const modelRoutes = new Hono()

modelRoutes.get("/", async (c) => {
  try {
    if (!state.models) {
      // This should be handled by startup logic, but as a fallback.
      await cacheModels()
    }

    const pricing = await readCopilotPricing()
    const allModels =
      state.models?.data.map((model) => {
        const modelPricing = pricingForModel(pricing, model.id)
        return {
          id: model.id,
          object: "model",
          type: "model",
          created: 0, // No date available from source
          created_at: new Date(0).toISOString(), // No date available from source
          owned_by: model.vendor,
          display_name: model.name,
          capabilities: model.capabilities,
          supported_endpoints: model.supported_endpoints,
          preview: model.preview,
          model_picker_enabled: model.model_picker_enabled,
          model_picker_category: model.model_picker_category,
          x_copilot_pricing:
            modelPricing ?
              {
                ...modelPricing,
                source_version: pricing?.source.version,
                stale: pricing?.source.stale,
              }
            : undefined,
        }
      }) ?? []

    const models = filterModels(
      allModels,
      state.hideInternal,
      state.modelFilter,
    )

    // Provenance markers identify the proxy translation code and the catalog
    // snapshot it routed on. They are not a guarantee of identical responses.
    c.header("X-Copilot-API-Translation-Contract", TRANSLATION_CONTRACT)
    c.header("X-Copilot-API-Build", BUILD_IDENTITY)
    c.header("X-Copilot-API-Catalog", state.modelsFingerprint ?? UNKNOWN_MARKER)
    c.header(
      "X-Copilot-API-Catalog-Observed-At",
      state.modelsObservedAt ?? UNKNOWN_MARKER,
    )

    return c.json({
      object: "list",
      data: models,
      has_more: false,
    })
  } catch (error) {
    return await forwardError(c, error)
  }
})

import { afterEach, beforeEach, describe, expect, it } from "bun:test"

import {
  BUILD_IDENTITY,
  TRANSLATION_CONTRACT,
  UNKNOWN_MARKER,
} from "~/lib/build-info"
import { state } from "~/lib/state"
import { server } from "~/server"

import packageJson from "../package.json"

const PROVENANCE_HEADERS = [
  "x-copilot-api-translation-contract",
  "x-copilot-api-build",
  "x-copilot-api-catalog",
  "x-copilot-api-catalog-observed-at",
]

describe("operational hardening", () => {
  it("reports the package version from health", async () => {
    const response = await server.request("/health")
    expect(response.status).toBe(200)
    expect(await response.json()).toMatchObject({
      status: "ok",
      version: packageJson.version,
    })
  })

  it.each(["/health", "/v1/models", "/token"])(
    "does not emit wildcard CORS by default for %s",
    async (path) => {
      const response = await server.request(path, {
        headers: { origin: "https://malicious.example" },
      })
      expect(response.headers.get("access-control-allow-origin")).toBeNull()
    },
  )

  it.each([
    "/v1/responses/resp_123",
    "/responses/resp_123",
    "/v1/conversations",
  ])("does not expose Responses lifecycle route %s", async (path) => {
    const response = await server.request(path)
    expect(response.status).toBe(404)
  })
})

describe("translation contract provenance markers", () => {
  const catalog = {
    object: "list",
    data: [
      {
        id: "gpt-provenance",
        name: "GPT Provenance",
        object: "model",
        vendor: "openai",
        version: "1",
        preview: false,
        model_picker_enabled: true,
        supported_endpoints: ["/responses"],
        capabilities: {
          family: "gpt",
          limits: {},
          object: "model_capabilities",
          supports: {},
          tokenizer: "test",
          type: "chat",
        },
      },
    ],
  }

  beforeEach(() => {
    state.models = structuredClone(catalog)
    state.modelsFingerprint = "0123456789abcdef"
    state.modelsObservedAt = "2026-08-13T00:00:00.000Z"
  })

  afterEach(() => {
    state.models = undefined
    state.modelsFingerprint = undefined
    state.modelsObservedAt = undefined
  })

  it.each(["/models", "/v1/models"])(
    "marks %s with provenance",
    async (path) => {
      const response = await server.request(path)
      expect(response.status).toBe(200)
      expect(response.headers.get("x-copilot-api-translation-contract")).toBe(
        TRANSLATION_CONTRACT,
      )
      expect(response.headers.get("x-copilot-api-build")).toBe(BUILD_IDENTITY)
      expect(response.headers.get("x-copilot-api-catalog")).toBe(
        "0123456789abcdef",
      )
      expect(response.headers.get("x-copilot-api-catalog-observed-at")).toBe(
        "2026-08-13T00:00:00.000Z",
      )
    },
  )

  it("emits identical markers on both mounted paths", async () => {
    const [mounted, versioned] = await Promise.all([
      server.request("/models"),
      server.request("/v1/models"),
    ])
    for (const header of PROVENANCE_HEADERS) {
      expect(versioned.headers.get(header)).toBe(mounted.headers.get(header))
    }
  })

  it("reports the package version in the build identity", async () => {
    const response = await server.request("/v1/models")
    expect(response.headers.get("x-copilot-api-build")).toStartWith(
      `${packageJson.version}+`,
    )
  })

  it("leaves the model list body unchanged", async () => {
    const response = await server.request("/v1/models")
    expect(await response.json()).toMatchObject({
      object: "list",
      has_more: false,
      data: [{ id: "gpt-provenance", object: "model" }],
    })
  })

  it("falls back to unknown when no catalog snapshot is recorded", async () => {
    state.modelsFingerprint = undefined
    state.modelsObservedAt = undefined

    const response = await server.request("/v1/models")
    expect(response.headers.get("x-copilot-api-catalog")).toBe(UNKNOWN_MARKER)
    expect(response.headers.get("x-copilot-api-catalog-observed-at")).toBe(
      UNKNOWN_MARKER,
    )
  })

  it("never exposes secrets, identity or per-request counters", async () => {
    state.githubToken = "gho_secret_github_token"
    state.copilotToken = "copilot_secret_token"

    const response = await server.request("/v1/models")
    const rendered = [...response.headers.entries()]
      .map(([name, value]) => `${name}: ${value}`)
      .join("\n")

    expect(rendered).not.toContain("gho_secret_github_token")
    expect(rendered).not.toContain("copilot_secret_token")
    expect(rendered).not.toContain("/Users/")
    expect(rendered.toLowerCase()).not.toContain("uptime")
    expect(rendered.toLowerCase()).not.toContain("exp-assignment")

    state.githubToken = undefined
    state.copilotToken = undefined
  })

  it("keeps markers stable across repeated requests to one snapshot", async () => {
    const first = await server.request("/v1/models")
    const second = await server.request("/v1/models")
    for (const header of PROVENANCE_HEADERS) {
      expect(second.headers.get(header)).toBe(first.headers.get(header))
    }
  })
})
